/**
 * Title-screen textures generated by scripts/assets/gen-title.mjs.
 * TitleScene.preload() calls preloadTitleAssets(this) (no BootScene wiring needed); every consumer
 * checks scene.textures.exists() and simply skips the effect if a file failed to load.
 */
import { getAssetPath } from '../../utils/assetBase.js';

export const TITLE_DIR = 'assets/UI/title';
export const TITLE_TEX = Object.freeze({
  /** 32x32 soft white radial dot: twinkles, motes, glows (tinted + ADD blend). */
  dot: 'title-dot'
});

/** @returns {Array<{key:string,path:string}>} */
export function titleAssetManifest() {
  return [{ key: TITLE_TEX.dot, path: `${TITLE_DIR}/dot.png` }];
}

export function preloadTitleAssets(scene) {
  for (const a of titleAssetManifest()) {
    if (scene.textures && scene.textures.exists(a.key)) continue;
    scene.load.image(a.key, getAssetPath(a.path));
  }
}
